// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up the depositor account
        address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

        // Call setL1BlockValues with a specific _timestamp value
        vm.prank(depositor);
        c.setL1BlockValues(
            1,           // _number
            42,          // _timestamp  (the key value)
            100,         // _basefee
            0x00,        // _hash
            2,           // _sequenceNumber
            0x01,        // _batcherHash
            200,         // _l1FeeOverhead
            300          // _l1FeeScalar
        );

        // Assert that timestamp equals 42 (reference sets it, buggy version does not)
        assertTrue(c.timestamp() == 42, "timestamp should have been updated to 42");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // 1. Set up the caller as the depositor account
        vm.prank(0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        // 2. Call setL1BlockValues with _timestamp=123
        c.setL1BlockValues(1, 123, 2, bytes32(0x03), 4, bytes32(0x05), 6, 7);
        // 3. Assert that timestamp is 123 (reference holds, bug breaks because timestamp remains 0)
        assertTrue(c.timestamp() == 123);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        vm.prank(0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        c.setL1BlockValues(1, 2, 3, keccak256("x"), 4, keccak256("y"), 5, 42);
        assertTrue(c.l1FeeScalar() == 0);
    }
}
